import{_ as t,o as d,c as a,a6 as o}from"./chunks/framework.BrkgobfX.js";const b=JSON.parse('{"title":"会话与上下文管理","description":"目录访问、上下文压缩、分支与回滚、导出与恢复","frontmatter":{"title":"会话与上下文管理","description":"目录访问、上下文压缩、分支与回滚、导出与恢复","source":"https://daiw.org/manual/claude-code/commands-session"},"headers":[],"relativePath":"manual/agent/claude-code/commands-session.md","filePath":"manual/agent/claude-code/commands-session.md"}'),c={name:"manual/agent/claude-code/commands-session.md"};function s(n,e,r,l,i,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="会话与上下文管理" tabindex="-1">会话与上下文管理 <a class="header-anchor" href="#会话与上下文管理" aria-label="Permalink to &quot;会话与上下文管理&quot;">​</a></h1><blockquote><p>目录访问、上下文压缩、分支与回滚、导出与恢复</p></blockquote><p><code>/</code> 只有出现在消息<strong>开头</strong>才会被识别为命令，后面的文字会作为该命令的参数。输入 <code>/</code> 可以看到当前可用的全部命令，输入 <code>/</code> 加字母可以过滤。</p><h2 id="目录与工作区" tabindex="-1">目录与工作区 <a class="header-anchor" href="#目录与工作区" aria-label="Permalink to &quot;目录与工作区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/add-dir &lt;path&gt;</code></td><td>为当前会话额外授权一个工作目录的文件读写权限。注意：这只授予文件访问，不会自动发现该目录下的 <code>.claude/</code> 配置（<code>.claude/skills/</code> 除外）。v2.1.257 起传入当前工作目录内的子目录也行，会像 <code>--add-dir</code> 一样加载其技能、命令与 agent；网络路径（UNC 共享、<code>/net/&lt;host&gt;</code>）一律拒绝</td></tr><tr><td><code>/cd &lt;path&gt;</code></td><td>把当前会话切换到新的工作目录，同时保留 prompt 缓存——新目录的 <code>CLAUDE.md</code> 会作为一条消息追加，而不是重建整个系统提示词（v2.1.169+）。⚠️ v2.1.246 起新目录的项目设置、hooks、<code>.mcp.json</code> 服务器（照常需审批）、技能与 agent 切过去立即生效，不必再 <code>--resume</code></td></tr></tbody></table><h2 id="上下文管理" tabindex="-1">上下文管理 <a class="header-anchor" href="#上下文管理" aria-label="Permalink to &quot;上下文管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/compact [instructions]</code></td><td>总结当前对话以释放上下文空间，可传入聚焦说明，例如 <code>/compact 只保留和认证模块相关的内容</code>。🆕 v2.1.299 起超过 200K token 的对话闲置约 54 分钟后，会在 1 小时 prompt 缓存过期前自动触发<strong>空闲压缩</strong>（Idle compaction，v2.1.314 起 VS Code、Claude Desktop Code 标签页及开启 1 小时缓存的云厂商/网关会话也支持），可在 <code>/config</code> 或 <code>settings.json</code> 的 <code>&quot;idleCompaction&quot;: false</code> 关闭</td></tr><tr><td><code>/context [all]</code></td><td>用彩色网格可视化当前上下文占用情况，给出优化建议；传 <code>all</code> 展开每一项明细。v2.1.283 起 MCP 服务器说明（server instructions）单列一行并计入总量；v2.1.281 起总量也算上上次回复之后新增的消息，因此可能比状态栏显示的高</td></tr><tr><td><code>/clear [name]</code></td><td>开启一个全新对话（项目记忆仍保留），之前的对话仍可通过 <code>/resume</code> 找回；可传名称标注旧对话。别名 <code>/reset</code>、<code>/new</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><code>/compact</code> 是“总结当前对话、继续同一个任务”；<code>/clear</code> 是“另起一个任务”。上下文快满时优先用前者，任务已经完成、准备做别的事情时用后者。</p></div><h2 id="分支、检查点与回滚" tabindex="-1">分支、检查点与回滚 <a class="header-anchor" href="#分支、检查点与回滚" aria-label="Permalink to &quot;分支、检查点与回滚&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/branch [name]</code></td><td>在当前节点创建一个对话分支，尝试不同方向而不丢失原对话；原对话仍可通过 <code>/resume</code> 找回</td></tr><tr><td><code>/rewind</code></td><td>把对话和/或代码回滚到之前的某个检查点，或者从某条消息开始重新总结。别名 <code>/checkpoint</code>、<code>/undo</code>（⚠️ v2.1.309 起 <code>sed -i</code> 按普通 Bash 命令执行，不再由 <code>/rewind</code> 恢复）</td></tr></tbody></table><h2 id="恢复与导出" tabindex="-1">恢复与导出 <a class="header-anchor" href="#恢复与导出" aria-label="Permalink to &quot;恢复与导出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/resume [session]</code></td><td>按 ID/名称恢复对话，或打开会话选择器；后台会话会标记 <code>bg</code>。别名 <code>/continue</code></td></tr><tr><td><code>/rename [name]</code></td><td>重命名当前会话，显示在 prompt bar 上；不传名称则根据对话内容自动生成</td></tr><tr><td><code>/export [filename]</code></td><td>把当前对话导出为纯文本；不传文件名则弹出选择“复制到剪贴板”或“保存文件”</td></tr><tr><td><code>/copy [N]</code></td><td>复制最近一条（或倒数第 N 条）assistant 回复；含代码块时会弹出选择器（🆕 v2.1.295 起选择器还提供引用文本项，复制草稿时去掉 <code>&gt;</code> 前缀）</td></tr></tbody></table><h2 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/btw &lt;question&gt;</code></td><td>问一个不计入对话历史的旁支问题；v2.1.257 起用 <code>Shift+←</code> / <code>Shift+→</code>（或 <code>[</code> / <code>]</code>）翻看最近问过的旁支问题</td></tr><tr><td><code>/recap</code></td><td>手动生成当前会话的一句话摘要</td></tr><tr><td><code>/exit</code></td><td>退出 CLI；如果当前是 attach 到后台会话，则只是 detach，会话继续在后台跑。别名 <code>/quit</code></td></tr></tbody></table><h2 id="典型时序" tabindex="-1">典型时序 <a class="header-anchor" href="#典型时序" aria-label="Permalink to &quot;典型时序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude                     # 进入项目，开始一次会话</span></span>
<span class="line"><span>...(工作一段时间，上下文变长)</span></span>
<span class="line"><span>/context                   # 看看上下文都花在哪了</span></span>
<span class="line"><span>/compact 聚焦在登录模块的改动</span></span>
<span class="line"><span>...(继续工作)</span></span>
<span class="line"><span>/clear 完成登录模块重构      # 任务切换，给旧对话留个名字</span></span>
<span class="line"><span>...(第二天)</span></span>
<span class="line"><span>claude --resume &quot;完成登录模块重构&quot;   # 或交互式 /resume 选择器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div>`,16)])])}const u=t(c,[["render",s]]);export{b as __pageData,u as default};
